"use client";
import {useEffect,useMemo,useRef,useState,type ClipboardEvent,type KeyboardEvent,type FormEvent} from "react";

type Result={id?:number,name:string,email:string,wpm:number,accuracy:number,infractions:number,plates:number,windows:number,overall:number,status:string,practicalAnswers?:string,responseDetails?:string};
type PracticalAnswerKey={plate:string,vehicle:string,infraction:string,validity:"VÁLIDA"|"INVÁLIDA"};
type PracticalConfig=typeof defaultPractical;
type OcrCase={image:string,correctPlate:string,ocrPlate:string,correctCategory:string,shownCategory:string};
type OcrAnswer={plateStatus:""|"correct"|"divergent",correctedPlate:string,categoryStatus:""|"correct"|"divergent",correctedCategory:string};
type AttentionEvent={startedAt:string,endedAt:string,durationSeconds:number,reason:"Aba oculta ou janela minimizada"|"Troca de janela"};
type CandidateProfile={phone:string,address:string,pcd:"Sim"|"Não"|""};
type SortKey="name"|"pcd"|"wpm"|"plates"|"windows"|"infractions"|"attention"|"overall"|"status";
const defaultText="O processamento de imagens exige atenção, concentração e responsabilidade em todas as etapas. Cada registro deve ser observado com cuidado para que as informações sejam digitadas de forma correta e completa. Antes de concluir uma análise, é importante conferir a placa do veículo, comparar letras e números semelhantes, verificar a qualidade da imagem e confirmar se os dados inseridos correspondem ao que está visível. Pequenos erros de digitação podem comprometer o resultado final e gerar retrabalho para toda a equipe. Por isso, o profissional deve manter um ritmo constante sem deixar de lado a precisão. Também é fundamental saber utilizar o computador, organizar arquivos e pastas, reconhecer os atalhos mais usados e seguir corretamente os procedimentos definidos pela empresa. Quando houver dúvida, a melhor conduta é revisar o registro antes de avançar. Agilidade é importante, mas deve sempre caminhar junto com a assertividade, o cuidado com as informações e o compromisso com a qualidade do serviço realizado.";
const scenes=[
 {title:"Avanço de sinal",desc:"O veículo ultrapassa a linha de retenção após o início da fase vermelha.",opts:["Avanço de sinal vermelho","Excesso de velocidade","Parada sobre a faixa","Conversão proibida"],ok:0},
 {title:"Faixa exclusiva",desc:"Automóvel particular circula em corredor sinalizado para ônibus no horário de restrição.",opts:["Estacionamento irregular","Trânsito em faixa exclusiva","Ultrapassagem proibida","Veículo sem identificação"],ok:1},
 {title:"Conversão à esquerda",desc:"O condutor realiza conversão onde a sinalização proíbe a manobra.",opts:["Retorno proibido","Avanço de sinal","Conversão proibida","Circulação no acostamento"],ok:2}
];
const defaultPlates=["BRA2E19","QXZ7J42","RHC4A08","MKT9D31","ABC1C23"];
const practicalCases=[
 {images:["/ocorrencias/caso-1a.jpg","/ocorrencias/caso-1b.jpg","/ocorrencias/caso-1c.jpg"]},
 {images:["/ocorrencias/caso-2.jpg"]},
 {images:["/ocorrencias/caso-3.jpg"]},
 {images:["/ocorrencias/caso-4a.jpg","/ocorrencias/caso-4b.jpg","/ocorrencias/caso-4c.jpg"]},
 {images:["/ocorrencias/caso-5a.jpg","/ocorrencias/caso-5b.jpg"]}
];
const defaultOcrCases:OcrCase[]=[
 {image:"/ocr/caso1.jpg",correctPlate:"SMA2A86",ocrPlate:"SMA2A86",correctCategory:"CARRO",shownCategory:"CARRO"},
 {image:"/ocr/caso2.jpg",correctPlate:"RXQ0D34",ocrPlate:"RXQ0034",correctCategory:"CARRO",shownCategory:"CARRO"},
 {image:"/ocr/caso3.jpg",correctPlate:"SXS6I45",ocrPlate:"SXS6145",correctCategory:"MOTO",shownCategory:"CARRO"},
 {image:"/ocr/caso4.jpg",correctPlate:"FRV7890",ocrPlate:"FRY7890",correctCategory:"CARRO",shownCategory:"CARRO"},
 {image:"/ocr/caso5.jpg",correctPlate:"UAI0C37",ocrPlate:"UAI0C37",correctCategory:"CAMINHÃO",shownCategory:"CAMINHÃO"}
];
const blankOcrAnswer=():OcrAnswer=>({plateStatus:"",correctedPlate:"",categoryStatus:"",correctedCategory:""});
const defaultPractical={platePrompt:"Digite a placa do veículo:",vehiclePrompt:"Tipo de veículo:",infractionPrompt:"Qual infração está sendo cometida?",validityPrompt:"Você julga a infração válida?",vehicleTypes:["Carro","Moto","Caminhão","Ônibus","Utilitário"],infractionTypes:["Excesso de velocidade","Avanço de sinal","Parada sobre a faixa","Conversão proibida","Não é possível identificar"],answerKey:[{plate:"MGF3820",vehicle:"MOTO",infraction:"AVANÇO DE SINAL",validity:"VÁLIDA"},{plate:"ERT7511",vehicle:"CARRO",infraction:"EXCESSO DE VELOCIDADE",validity:"VÁLIDA"},{plate:"BDW7H52",vehicle:"CARRO",infraction:"EXCESSO DE VELOCIDADE",validity:"VÁLIDA"},{plate:"BAM1A69",vehicle:"CARRO",infraction:"AVANÇO DE SINAL",validity:"VÁLIDA"},{plate:"RGE6I22",vehicle:"CARRO",infraction:"PARADA SOBRE A FAIXA",validity:"VÁLIDA"}] as PracticalAnswerKey[]};
const defaultWin=[
 ["O que acontece quando você pressiona Ctrl C?",["Cola o texto","Copia o texto","Salva o documento"],1],
 ["O que acontece quando você pressiona Ctrl V?",["Abre um novo documento","Fecha o programa","Cola o texto"],2],
 ["O que é a área de trabalho (desktop)?",["O lugar onde você armazena arquivos","A tela inicial do computador","Um programa de edição"],1],
 ["O que é um zip?",["Um tipo de arquivo comprimido que reduz o tamanho de dados","Um programa de edição de imagens","Um dispositivo de armazenamento externo"],0],
 ["Como bloqueia a tela do computador?",["Ctrl + L","Windows + P","Windows + L"],2],
 ["Qual é a ação que a tecla Backspace executa?",["Apaga o caractere à esquerda do cursor","Apaga o caractere à direita do cursor","Move o cursor para uma posição à direita"],0],
 ["Qual é a ação que a tecla Enter faz?",["Salva o documento","Cria uma nova linha ou executa um comando","Apaga o texto"],1],
 ["O que é uma pasta no computador?",["Um tipo de arquivo de texto","Um local para armazenar arquivos e documentos","Um programa de edição de arquivos"],1],
 ["Qual comando é utilizado para selecionar todo o texto?",["Ctrl C","Ctrl A","Ctrl T"],1],
 ["O que é um arquivo?",["Um programa de computador","Um documento ou informação armazenada","Um tipo de hardware"],1]
] as [string,string[],number][];
const initial:Result[]=[];
const stages=["Digitação","Placas","Informática","Análise OCR","Análise prática"];
const formatTime=(seconds:number)=>`${String(Math.floor(seconds/60)).padStart(2,"0")}:${String(seconds%60).padStart(2,"0")}`;
const editDistance=(expected:string,actual:string)=>{
 const previous=Array.from({length:actual.length+1},(_,i)=>i);
 for(let i=1;i<=expected.length;i++){
  const current=[i];
  for(let j=1;j<=actual.length;j++)current[j]=expected[i-1]===actual[j-1]?previous[j-1]:Math.min(previous[j-1],previous[j],current[j-1])+1;
  previous.splice(0,previous.length,...current);
 }
 return previous[actual.length];
};
const readTimes=(result:Result)=>{try{const details=JSON.parse(result.responseDetails||"{}") as {timings?:{typing?:number,plates?:number,total?:number}};return{typing:details.timings?.typing||0,plates:details.timings?.plates||0,total:details.timings?.total||0}}catch{return{typing:0,plates:0,total:0}}};
const readAttention=(result:Result)=>{try{const details=JSON.parse(result.responseDetails||"{}") as {attentionEvents?:AttentionEvent[]};const events=details.attentionEvents||[];return{count:events.length,total:events.reduce((sum,item)=>sum+item.durationSeconds,0),events}}catch{return{count:0,total:0,events:[] as AttentionEvent[]}}};
const readProfile=(result:Result):CandidateProfile=>{try{const details=JSON.parse(result.responseDetails||"{}") as {candidateProfile?:CandidateProfile};return details.candidateProfile||{phone:"",address:"",pcd:""}}catch{return{phone:"",address:"",pcd:""}}};
const readPracticalScore=(result:Result)=>{try{return (JSON.parse(result.responseDetails||"{}") as {practicalScore?:number}).practicalScore??0}catch{return 0}};
const normalizeAnswer=(value:string)=>value.trim().normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase();
const blockClipboard=(event:ClipboardEvent<HTMLElement>)=>event.preventDefault();
const blockClipboardKeys=(event:KeyboardEvent<HTMLElement>)=>{
 if((event.ctrlKey||event.metaKey)&&["c","v","x"].includes(event.key.toLowerCase()))event.preventDefault();
};
function Logo(){return <div className="brand perkonsBrand"><img src="/perkons-logo.png" alt="Perkons"/><span><b>Processo Seletivo</b><small>PROCESSAMENTO DE IMAGENS</small></span></div>}
function Access({onCandidate,onAdmin}:{onCandidate:()=>void,onAdmin:()=>void}){return <div className="page"><header><Logo/><small>● Ambiente seguro</small></header><main className="landing"><section className="hero"><label>PROCESSO SELETIVO · PROCESSAMENTO DE IMAGENS</label><h1>Precisão em cada<br/><em>detalhe.</em></h1><p>Uma jornada prática para identificar profissionais atentos, ágeis e preparados para transformar imagens em informações confiáveis.</p><div className="mini"><span><b>4</b> etapas</span><span><b>~25</b> minutos</span><span><b>2</b> tentativas</span></div></section><section className="access"><h2>Como deseja acessar?</h2><p>Escolha seu perfil para continuar.</p><button className="dark" onClick={onCandidate}><i>◎</i><span><b>Sou candidato</b><small>Realizar minha avaliação</small></span><strong>→</strong></button><button onClick={onAdmin}><i>▦</i><span><b>Acesso administrativo</b><small>Acompanhar resultados</small></span><strong>→</strong></button><small>🔒 Seus dados são tratados com segurança.</small></section></main></div>}
function AdminLogin({onSuccess,onBack}:{onSuccess:(results:Result[])=>void,onBack:()=>void}){const[password,setPassword]=useState("");const[error,setError]=useState("");const[loading,setLoading]=useState(false);const submit=async(event:FormEvent)=>{event.preventDefault();setLoading(true);setError("");try{const login=await fetch("/api/admin-auth",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({password})});const data=await login.json();if(!login.ok)throw new Error(data.error||"Senha incorreta");const response=await fetch("/api/results");const resultData=await response.json();onSuccess(resultData.results||[])}catch(e){setError(e instanceof Error?e.message:"Não foi possível entrar")}finally{setLoading(false)}};return <div className="page adminLoginPage"><header><Logo/><button className="link" onClick={onBack}>← Voltar</button></header><main><form className="adminLogin" onSubmit={submit}><div className="adminLock">▦</div><label>ÁREA RESTRITA</label><h1>Acesso administrativo</h1><p>Informe a senha para visualizar candidatos, resultados e configurações.</p><label className="passwordLabel">Senha administrativa<input autoFocus required type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Digite sua senha"/></label>{error&&<p className="loginError">{error}</p>}<button disabled={loading}>{loading?"Entrando...":"Entrar no painel →"}</button></form></main></div>}
function Progress({step}:{step:number}){return <div className="progress">{stages.map((x,i)=><span className={i<step?"done":i===step?"active":""} key={x}><b>{i<step?"✓":i+1}</b><small>{x}</small></span>)}</div>}
function CandidateDetails({result,onClose,questions}:{result:Result,onClose:()=>void,questions:[string,string[],number][]}){
 const parse=<T,>(value:string|undefined,fallback:T):T=>{try{return value?JSON.parse(value) as T:fallback}catch{return fallback}};
 const details=parse<{typedText?:string,plateAnswers?:string[],windowsAnswers?:number[],questionSnapshot?:[string,string[],number][],ocrAnswers?:OcrAnswer[],ocrCaseSnapshot?:OcrCase[],attentionEvents?:AttentionEvent[],practicalScore?:number}>(result.responseDetails,{});
 const displayQuestions=details.questionSnapshot?.length?details.questionSnapshot:questions;
 const cases=parse<{plate:string,vehicle:string,infraction:string,validity:string,justification?:string}[]>(result.practicalAnswers,[]);
 const profile=readProfile(result);
 return <div className="candidateOverlay" role="dialog" aria-modal="true" aria-label={`Respostas de ${result.name}`}><div className="candidateDetail"><header><div><label>RESPOSTAS DO CANDIDATO</label><h2>{result.name}</h2></div><button onClick={onClose} aria-label="Fechar">×</button></header><div className="detailSummary"><span>Pontuação geral <b>{result.overall}%</b></span><span>Status <b>{result.status}</b></span><span>Saídas da tela <b>{details.attentionEvents?.length||0}</b></span><span className={`pcdSummary ${profile.pcd==="Sim"?"isPcd":""}`}>PCD <b>{profile.pcd||"Não informado"}</b></span><span>Tempo total <b>{readTimes(result).total?formatTime(readTimes(result).total):"Não registrado"}</b></span></div><details className="contactDetails"><summary>Exibir dados de contato</summary><div><span><small>E-mail</small><b>{result.email||"Não informado"}</b></span><span><small>Telefone</small><b>{profile.phone||"Não informado"}</b></span><span className="full"><small>Endereço</small><b>{profile.address||"Não informado"}</b></span></div></details><section className={`attentionReport ${details.attentionEvents?.length?"hasEvents":"noEvents"}`}><h3>Monitoramento de foco da avaliação</h3>{details.attentionEvents?.length?<><p>Foram registradas <b>{details.attentionEvents.length} saída(s)</b> da tela, totalizando <b>{formatTime(details.attentionEvents.reduce((sum,item)=>sum+item.durationSeconds,0))}</b>.</p><ol>{details.attentionEvents.map((item,i)=><li key={`${item.startedAt}-${i}`}><span>{item.reason}</span><b>{new Date(item.startedAt).toLocaleTimeString("pt-BR")} · {formatTime(item.durationSeconds)}</b></li>)}</ol></>:<p>Nenhuma troca de aba, janela ou minimização foi registrada.</p>}</section><section className="answerStage"><div className="answerStageHead"><i>1</i><div><h3>Teste de digitação</h3><p>{result.wpm} ppm · {result.accuracy}% de precisão</p></div></div>{details.typedText?<blockquote>{details.typedText}</blockquote>:<p className="unavailable">Texto digitado não disponível para este resultado antigo.</p>}</section><section className="answerStage"><div className="answerStageHead"><i>2</i><div><h3>Digitação de placas</h3><p>{result.plates}% de acertos</p></div></div>{details.plateAnswers?.length?<div className="answerGrid">{details.plateAnswers.map((x,i)=><span key={i}><small>Placa {i+1}</small><b>{x||"Não respondida"}</b></span>)}</div>:<p className="unavailable">Respostas individuais não disponíveis para este resultado antigo.</p>}</section><section className="answerStage"><div className="answerStageHead"><i>3</i><div><h3>Informática básica</h3><p>{result.windows}% de acertos</p></div></div>{details.windowsAnswers?.length?<ol className="computerAnswers">{displayQuestions.map((q,i)=><li key={q[0]}><span>{q[0]}</span><b>{details.windowsAnswers?.[i]===undefined?"Não respondida":`${String.fromCharCode(65+(details.windowsAnswers[i]??0))}) ${q[1][details.windowsAnswers[i]??0]}`}</b></li>)}</ol>:<p className="unavailable">Alternativas marcadas não disponíveis para este resultado antigo.</p>}</section><section className="answerStage"><div className="answerStageHead"><i>4</i><div><h3>Análise OCR</h3><p>{result.infractions}% de acertos</p></div></div>{details.ocrAnswers?.length?<div className="ocrAnswerDetails">{details.ocrAnswers.map((x,i)=><article key={i}><h4>Caso {i+1}</h4><p><b>Placa:</b> {x.plateStatus==="correct"?"Marcada como correta":`Divergente · correção ${x.correctedPlate||"não informada"}`}</p><p><b>Categoria:</b> {x.categoryStatus==="correct"?"Marcada como correta":`Divergente · correção ${x.correctedCategory||"não informada"}`}</p></article>)}</div>:<p className="unavailable">Análise OCR não disponível para este resultado antigo.</p>}</section><section className="answerStage"><div className="answerStageHead"><i>5</i><div><h3>Análise prática</h3><p>{details.practicalScore??0}% de acertos · respostas das cinco ocorrências</p></div></div>{cases.length?<div className="practicalAnswers">{cases.map((x,i)=><article key={i}><h4>Ocorrência {i+1}</h4><dl><div><dt>Placa</dt><dd>{x.plate}</dd></div><div><dt>Veículo</dt><dd>{x.vehicle}</dd></div><div><dt>Infração</dt><dd>{x.infraction}</dd></div><div><dt>Validade</dt><dd>{x.validity||"Não respondida"}</dd></div><div className="full"><dt>Justificativa</dt><dd>{x.justification||"Não informada"}</dd></div></dl></article>)}</div>:<p className="unavailable">Análise prática não disponível para este resultado antigo.</p>}</section><button className="closeDetail" onClick={onClose}>Fechar respostas</button></div></div>
}
function AdminTestEditor({typingText,setTypingText,plates,setPlates,questions,editQuestion,deleteQuestion,setQuestions,ocrCases,setOcrCases,practicalConfig,setPracticalConfig,save,saving,message}:{typingText:string,setTypingText:(value:string)=>void,plates:string[],setPlates:(value:string[])=>void,questions:[string,string[],number][],editQuestion:(i:number,field:"question"|"answer"|number,value:string|number)=>void,deleteQuestion:(i:number)=>void,setQuestions:(value:[string,string[],number][])=>void,ocrCases:OcrCase[],setOcrCases:(value:OcrCase[])=>void,practicalConfig:PracticalConfig,setPracticalConfig:(value:PracticalConfig)=>void,save:()=>void,saving:boolean,message:string}){
 const changeList=(key:"vehicleTypes"|"infractionTypes",i:number,value:string)=>setPracticalConfig({...practicalConfig,[key]:practicalConfig[key].map((x,index)=>index===i?value:x)});
 const deleteList=(key:"vehicleTypes"|"infractionTypes",i:number)=>{if(practicalConfig[key].length===1)return;setPracticalConfig({...practicalConfig,[key]:practicalConfig[key].filter((_,index)=>index!==i)})};
 const updatePracticalKey=(i:number,key:keyof PracticalAnswerKey,value:string)=>setPracticalConfig({...practicalConfig,answerKey:practicalConfig.answerKey.map((item,index)=>index===i?{...item,[key]:key==="validity"?value as PracticalAnswerKey["validity"]:value.toUpperCase()}:item)});
 return <section className="questionEditor"><div className="questionEditorHead"><div><h2>Configuração de todas as etapas</h2><p>As alterações salvas serão usadas nas próximas avaliações.</p></div><button onClick={save} disabled={saving}>{saving?"Salvando...":"Salvar todas as alterações"}</button></div>{message&&<p className="questionMessage">{message}</p>}
 <article><header><b>Etapa 1 · Teste de digitação</b><span>Texto de referência</span></header><label>Texto apresentado ao candidato<textarea className="largeEditor" value={typingText} onChange={e=>setTypingText(e.target.value)}/></label></article>
 <article><header><b>Etapa 2 · Digitação de placas</b><span>{plates.length} placas</span></header><div className="editableRows">{plates.map((plate,i)=><label key={i}><span>{i+1}</span><input maxLength={7} value={plate} onChange={e=>setPlates(plates.map((x,index)=>index===i?e.target.value.toUpperCase():x))}/><button type="button" className="dangerButton" disabled={plates.length===1} onClick={()=>confirm(`Excluir a placa ${i+1}?`)&&setPlates(plates.filter((_,index)=>index!==i))}>Excluir</button></label>)}</div><button type="button" className="addButton" onClick={()=>setPlates([...plates,""])}>+ Adicionar placa</button></article>
 <div className="editorSectionTitle"><div><b>Etapa 3 · Informática básica</b><small>Edite, adicione ou exclua perguntas.</small></div><button type="button" className="addButton" onClick={()=>setQuestions([...questions,["Nova pergunta",["Alternativa A","Alternativa B","Alternativa C"],0]])}>+ Adicionar pergunta</button></div>
 {questions.map((q,i)=><article key={i}><header><b>Questão {i+1}</b><button type="button" className="dangerButton" onClick={()=>deleteQuestion(i)}>Excluir pergunta</button></header><label>Enunciado<textarea value={q[0]} onChange={e=>editQuestion(i,"question",e.target.value)}/></label><div className="optionEditor">{q[1].map((option,j)=><label key={j}><span>{String.fromCharCode(65+j)})</span><input value={option} onChange={e=>editQuestion(i,j,e.target.value)}/></label>)}</div><label className="correctAnswer">Resposta correta<select value={q[2]} onChange={e=>editQuestion(i,"answer",Number(e.target.value))}>{q[1].map((option,j)=><option value={j} key={j}>{String.fromCharCode(65+j)}) {option||`Alternativa ${j+1}`}</option>)}</select></label></article>)}
 <article><header><b>Etapa 4 · Análise OCR</b><span>{ocrCases.length} cenários</span></header><p>Edite os valores exibidos pelo OCR e os valores corretos usados na pontuação.</p><div className="ocrAdminGrid">{ocrCases.map((item,i)=><section key={item.image}><img src={item.image} alt={`Caso OCR ${i+1}`}/><h4>Caso {i+1}</h4>{([['ocrPlate','Placa exibida pelo OCR'],['correctPlate','Placa correta'],['shownCategory','Categoria exibida'],['correctCategory','Categoria correta']] as [keyof OcrCase,string][]).map(([key,label])=><label key={key}>{label}<input value={item[key]} onChange={e=>setOcrCases(ocrCases.map((x,index)=>index===i?{...x,[key]:e.target.value.toUpperCase()}:x))}/></label>)}</section>)}</div></article>
 <article><header><b>Etapa 5 · Análise prática</b><span>Perguntas e opções</span></header><div className="promptGrid">{(["platePrompt","vehiclePrompt","infractionPrompt","validityPrompt"] as const).map((key,i)=><label key={key}>Pergunta {i+1}<input value={practicalConfig[key]} onChange={e=>setPracticalConfig({...practicalConfig,[key]:e.target.value})}/></label>)}</div><h4>Gabarito da correção automática</h4><div className="ocrAdminGrid">{practicalConfig.answerKey.map((item,i)=><section key={i}><h4>Ocorrência {i+1}</h4><label>Placa correta<input maxLength={7} value={item.plate} onChange={e=>updatePracticalKey(i,"plate",e.target.value)}/></label><label>Tipo de veículo<input value={item.vehicle} onChange={e=>updatePracticalKey(i,"vehicle",e.target.value)}/></label><label>Infração<input value={item.infraction} onChange={e=>updatePracticalKey(i,"infraction",e.target.value)}/></label><label>Validade<select value={item.validity} onChange={e=>updatePracticalKey(i,"validity",e.target.value)}><option>VÁLIDA</option><option>INVÁLIDA</option></select></label></section>)}</div><p>A justificativa é apenas informativa e não faz parte da pontuação automática.</p><h4>Tipos de veículo</h4><div className="editableRows">{practicalConfig.vehicleTypes.map((value,i)=><label key={i}><span>{i+1}</span><input value={value} onChange={e=>changeList("vehicleTypes",i,e.target.value)}/><button type="button" className="dangerButton" disabled={practicalConfig.vehicleTypes.length===1} onClick={()=>deleteList("vehicleTypes",i)}>Excluir</button></label>)}</div><button type="button" className="addButton" onClick={()=>setPracticalConfig({...practicalConfig,vehicleTypes:[...practicalConfig.vehicleTypes,""]})}>+ Adicionar tipo</button><h4>Tipos de infração</h4><div className="editableRows">{practicalConfig.infractionTypes.map((value,i)=><label key={i}><span>{i+1}</span><input value={value} onChange={e=>changeList("infractionTypes",i,e.target.value)}/><button type="button" className="dangerButton" disabled={practicalConfig.infractionTypes.length===1} onClick={()=>deleteList("infractionTypes",i)}>Excluir</button></label>)}</div><button type="button" className="addButton" onClick={()=>setPracticalConfig({...practicalConfig,infractionTypes:[...practicalConfig.infractionTypes,""]})}>+ Adicionar infração</button></article>
 </section>
}
function ImageLightbox({images,index,setIndex,onClose}:{images:string[],index:number,setIndex:(index:number)=>void,onClose:()=>void}){const[scale,setScale]=useState(1);useEffect(()=>setScale(1),[index]);useEffect(()=>{const key=(event:globalThis.KeyboardEvent)=>{if(event.key==="Escape")onClose();if(event.key==="ArrowLeft")setIndex((index-1+images.length)%images.length);if(event.key==="ArrowRight")setIndex((index+1)%images.length);if(event.key==="+")setScale(x=>Math.min(3,x+.25));if(event.key==="-")setScale(x=>Math.max(1,x-.25))};window.addEventListener("keydown",key);return()=>window.removeEventListener("keydown",key)},[images,index,onClose,setIndex]);return <div className="imageLightbox" role="dialog" aria-modal="true" aria-label="Imagem ampliada" onClick={onClose}><div className="lightboxContent" onClick={e=>e.stopPropagation()}><button className="lightboxClose" onClick={onClose} aria-label="Fechar imagem">×</button><div className="lightboxViewport"><img style={{transform:`scale(${scale})`}} src={images[index]} alt={`Imagem ampliada ${index+1}`}/></div><div className="lightboxBar"><span>Imagem {index+1} de {images.length} · Zoom {Math.round(scale*100)}%</span><nav><button onClick={()=>setScale(x=>Math.max(1,x-.25))} disabled={scale===1}>− Zoom</button><button onClick={()=>setScale(x=>Math.min(3,x+.25))} disabled={scale===3}>+ Zoom</button><button onClick={()=>setScale(1)}>Restaurar</button>{images.length>1&&<><button onClick={()=>setIndex((index-1+images.length)%images.length)}>← Anterior</button><button onClick={()=>setIndex((index+1)%images.length)}>Próxima →</button></>}</nav></div></div></div>}
export default function Home(){
 const[view,setView]=useState<"access"|"candidate"|"admin-login"|"admin">("access");const[step,setStep]=useState(-1);const[user,setUser]=useState({name:"",email:"",phone:"",address:"",pcd:"" as CandidateProfile["pcd"]});const[typed,setTyped]=useState("");const[ia,setIa]=useState<number[]>([]);const[pa,setPa]=useState<string[]>(["","","","",""]);const[wa,setWa]=useState<number[]>([]);const[ocrCases,setOcrCases]=useState<OcrCase[]>(defaultOcrCases);const[ocrAnswers,setOcrAnswers]=useState<OcrAnswer[]>(defaultOcrCases.map(blankOcrAnswer));const[practical,setPractical]=useState(practicalCases.map(()=>({plate:"",vehicle:"",infraction:"",validity:"",justification:""})));const[attentionEvents,setAttentionEvents]=useState<AttentionEvent[]>([]);const[results,setResults]=useState(initial);const[selectedResult,setSelectedResult]=useState<Result|null>(null);const[query,setQuery]=useState("");const[statusFilter,setStatusFilter]=useState("Todos");const[pcdFilter,setPcdFilter]=useState("Todos");const[focusFilter,setFocusFilter]=useState("Todos");const[sortKey,setSortKey]=useState<SortKey>("overall");const[sortDir,setSortDir]=useState<"asc"|"desc">("desc");const[adminTab,setAdminTab]=useState<"overview"|"candidates"|"questions"|"settings">("overview");const[typingText,setTypingText]=useState(defaultText);const[testPlates,setTestPlates]=useState(defaultPlates);const[questions,setQuestions]=useState<[string,string[],number][]>(defaultWin);const[practicalConfig,setPracticalConfig]=useState<PracticalConfig>(defaultPractical);const[savingQuestions,setSavingQuestions]=useState(false);const[questionMessage,setQuestionMessage]=useState("");
 const[lightbox,setLightbox]=useState<{images:string[],index:number}|null>(null);
 const attentionStart=useRef<{startedAt:string,startMs:number,reason:AttentionEvent["reason"]}|null>(null);
 const testStartedAt=useRef<number|null>(null);
 const[stageSeconds,setStageSeconds]=useState(0);const[stageTimes,setStageTimes]=useState({typing:0,plates:0});
 useEffect(()=>{fetch("/api/questions").then(r=>r.json()).then(d=>{if(d.config){setTypingText(d.config.typingText);setTestPlates(d.config.plates);setPa(d.config.plates.map(()=>""));setQuestions(d.config.questions);const loaded=d.config.ocrCases?.length?d.config.ocrCases:defaultOcrCases;setOcrCases(loaded);setOcrAnswers(loaded.map(blankOcrAnswer));setPracticalConfig({...defaultPractical,...d.config.practical,answerKey:d.config.practical?.answerKey?.length?d.config.practical.answerKey:defaultPractical.answerKey})}else if(d.questions?.length)setQuestions(d.questions)}).catch(()=>{})},[]);
 useEffect(()=>{if(step!==0&&step!==1)return;const timer=window.setInterval(()=>setStageSeconds(value=>value+1),1000);return()=>window.clearInterval(timer)},[step]);
 useEffect(()=>{if(step<0||step>4)return;const begin=(reason:AttentionEvent["reason"])=>{if(attentionStart.current)return;attentionStart.current={startedAt:new Date().toISOString(),startMs:Date.now(),reason}};const end=()=>{const current=attentionStart.current;if(!current)return;attentionStart.current=null;setAttentionEvents(events=>[...events,{startedAt:current.startedAt,endedAt:new Date().toISOString(),durationSeconds:Math.max(1,Math.round((Date.now()-current.startMs)/1000)),reason:current.reason}])};const visibility=()=>document.visibilityState==="hidden"?begin("Aba oculta ou janela minimizada"):end();const blur=()=>{if(document.visibilityState!=="hidden")begin("Troca de janela")};window.addEventListener("blur",blur);window.addEventListener("focus",end);document.addEventListener("visibilitychange",visibility);return()=>{window.removeEventListener("blur",blur);window.removeEventListener("focus",end);document.removeEventListener("visibilitychange",visibility)}},[step]);
 const stats=useMemo(()=>{const expected=typingText.slice(0,typed.length),distance=editDistance(expected,typed),base=Math.max(expected.length,typed.length);const words=typed.trim()?typed.trim().split(/\s+/).length:0;const seconds=stageTimes.typing||stageSeconds;return{wpm:words?Math.round(words/Math.max(seconds/60,1/60)):0,accuracy:base?Math.max(0,Math.round((base-distance)/base*100)):100}},[typed,typingText,stageSeconds,stageTimes.typing]);
 const answer=(arr:number[],set:(x:number[])=>void,i:number,j:number)=>{const n=[...arr];n[i]=j;set(n)};
 const updatePractical=(i:number,key:"plate"|"vehicle"|"infraction"|"validity"|"justification",value:string)=>{const next=practical.map((item,index)=>index===i?{...item,[key]:value}:item);setPractical(next)};
 const updateOcr=(i:number,patch:Partial<OcrAnswer>)=>setOcrAnswers(current=>current.map((item,index)=>index===i?{...item,...patch}:item));
 const ocrComplete=ocrAnswers.length===ocrCases.length&&ocrAnswers.every(x=>x.plateStatus&&x.categoryStatus&&(x.plateStatus!=="divergent"||x.correctedPlate.length===7)&&(x.categoryStatus!=="divergent"||x.correctedCategory));
 const practicalComplete=practical.every(x=>x.plate.trim()&&x.vehicle&&x.infraction&&x.validity);
 const finish=()=>{if(!practicalComplete&&!confirm("Existem campos sem respostas. Deseja salvar desta forma?"))return;const pl=Math.round(pa.filter((x,i)=>x===testPlates[i]).length/testPlates.length*100),wi=Math.round(wa.filter((x,i)=>x===questions[i][2]).length/questions.length*100);let checks=0;ocrCases.forEach((item,i)=>{const a=ocrAnswers[i],plateSame=item.ocrPlate.toUpperCase()===item.correctPlate.toUpperCase(),categorySame=item.shownCategory.toUpperCase()===item.correctCategory.toUpperCase();if((plateSame&&a.plateStatus==="correct")||(!plateSame&&a.plateStatus==="divergent"&&a.correctedPlate.toUpperCase()===item.correctPlate.toUpperCase()))checks++;if((categorySame&&a.categoryStatus==="correct")||(!categorySame&&a.categoryStatus==="divergent"&&a.correctedCategory.toUpperCase()===item.correctCategory.toUpperCase()))checks++});const ocrScore=Math.round(checks/(ocrCases.length*2)*100);let practicalChecks=0;practical.forEach((item,i)=>{const key=practicalConfig.answerKey[i];if(!key)return;if(normalizeAnswer(item.plate)===normalizeAnswer(key.plate))practicalChecks++;if(normalizeAnswer(item.vehicle)===normalizeAnswer(key.vehicle))practicalChecks++;if(normalizeAnswer(item.infraction)===normalizeAnswer(key.infraction))practicalChecks++;if(normalizeAnswer(item.validity)===normalizeAnswer(key.validity))practicalChecks++});const practicalScore=Math.round(practicalChecks/(practicalCases.length*4)*100),overall=Math.round((stats.accuracy+pl+wi+ocrScore+practicalScore)/5);const result={...user,wpm:stats.wpm,accuracy:stats.accuracy,infractions:ocrScore,plates:pl,windows:wi,overall,status:overall>=85?"Aprovado":overall>=70?"Em análise":"Reprovado",practicalAnswers:JSON.stringify(practical),responseDetails:JSON.stringify({typedText:typed,plateAnswers:pa,windowsAnswers:wa,questionSnapshot:questions,ocrAnswers,ocrCaseSnapshot:ocrCases,practicalScore,practicalAnswerKeySnapshot:practicalConfig.answerKey,attentionEvents,candidateProfile:{phone:user.phone,address:user.address,pcd:user.pcd},timings:{...stageTimes,total:testStartedAt.current?Math.max(1,Math.round((Date.now()-testStartedAt.current)/1000)):0}})};setResults([result,...results]);fetch("/api/results",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(result)}).catch(()=>{});setStep(5)};
 const editQuestion=(i:number,field:"question"|"answer"|number,value:string|number)=>setQuestions(current=>current.map((q,index)=>index!==i?q:field==="question"?[String(value),q[1],q[2]]:field==="answer"?[q[0],q[1],Number(value)]:[q[0],q[1].map((option,j)=>j===field?String(value):option),q[2]]));
 const deleteQuestion=(i:number)=>{if(questions.length===1){setQuestionMessage("O teste precisa ter pelo menos uma pergunta.");return}if(confirm(`Excluir a questão ${i+1}?`))setQuestions(current=>current.filter((_,index)=>index!==i))};
 const saveQuestions=async()=>{setSavingQuestions(true);setQuestionMessage("");try{const config={typingText,plates:testPlates,questions,ocrCases,practical:practicalConfig};const response=await fetch("/api/questions",{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify({config})});const data=await response.json();if(!response.ok)throw new Error(data.error);setPa(testPlates.map(()=>""));setQuestionMessage("Todas as etapas foram salvas e atualizadas no teste.")}catch(error){setQuestionMessage(error instanceof Error?error.message:"Não foi possível salvar.")}finally{setSavingQuestions(false)}};
 if(view==="access")return <Access onCandidate={()=>setView("candidate")} onAdmin={()=>setView("admin-login")}/>;
 if(view==="admin-login")return <AdminLogin onBack={()=>setView("access")} onSuccess={loaded=>{setResults(loaded);setView("admin")}}/>;
 if(view==="admin"){
  const filtered=results.filter(r=>{const profile=readProfile(r),attention=readAttention(r);const search=(r.name+r.email+profile.phone+profile.address).toLowerCase().includes(query.toLowerCase());const normalizedStatus=r.status==="Não aprovado"?"Reprovado":r.status;const status=statusFilter==="Todos"||normalizedStatus===statusFilter;const pcd=pcdFilter==="Todos"||profile.pcd===pcdFilter;const focus=focusFilter==="Todos"||(focusFilter==="Com ocorrências"?attention.count>0:attention.count===0);return search&&status&&pcd&&focus});
  const sortValue=(r:Result,key:SortKey):string|number=>key==="name"?r.name.toLowerCase():key==="pcd"?readProfile(r).pcd:key==="wpm"?r.wpm:key==="plates"?r.plates:key==="windows"?r.windows:key==="infractions"?r.infractions:key==="attention"?readAttention(r).count:key==="overall"?r.overall:r.status.toLowerCase();
  const list=[...filtered].sort((a,b)=>{const av=sortValue(a,sortKey),bv=sortValue(b,sortKey);const comparison=typeof av==="number"&&typeof bv==="number"?av-bv:String(av).localeCompare(String(bv),"pt-BR");return sortDir==="asc"?comparison:-comparison});
  const toggleSort=(key:SortKey)=>{if(sortKey===key)setSortDir(direction=>direction==="asc"?"desc":"asc");else{setSortKey(key);setSortDir(key==="name"||key==="pcd"||key==="status"?"asc":"desc")}};
  const sortMark=(key:SortKey)=>sortKey===key?(sortDir==="asc"?" ↑":" ↓"):"";
  const avg=Math.round(results.reduce((a,r)=>a+r.overall,0)/results.length);
  const updateStatus=async(candidate:Result,status:string)=>{const previous=results;const same=(r:Result)=>candidate.id?r.id===candidate.id:r.email===candidate.email&&r.name===candidate.name;setResults(current=>current.map(r=>same(r)?{...r,status}:r));if(selectedResult&&same(selectedResult))setSelectedResult({...selectedResult,status});try{const response=await fetch("/api/results",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({id:candidate.id,email:candidate.email,status})});if(!response.ok)throw new Error()}catch{setResults(previous);if(selectedResult&&same(selectedResult))setSelectedResult(candidate);alert("Não foi possível salvar o novo status. Tente novamente.")}};
  const deleteCandidate=async(candidate:Result)=>{if(!candidate.id){alert("Este registro não pode ser excluído.");return}if(!confirm(`Excluir permanentemente todos os dados de ${candidate.name}? Esta ação não poderá ser desfeita.`))return;try{const response=await fetch("/api/results",{method:"DELETE",headers:{"content-type":"application/json"},body:JSON.stringify({id:candidate.id})});if(!response.ok)throw new Error();setResults(current=>current.filter(r=>r.id!==candidate.id));if(selectedResult?.id===candidate.id)setSelectedResult(null)}catch{alert("Não foi possível excluir o candidato. Tente novamente.")}};
  const statusClass=(status:string)=>status==="Aprovado"?"approved":status==="Em análise"?"analysis":status==="Banco"?"bank":"rejected";
  const table=<section className="panel"><div className="panelHead"><div><h2>Desempenho individual</h2><p>Clique no nome para visualizar todas as respostas.</p></div><input placeholder="⌕  Buscar candidato..." value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="tableFilters"><label>Status<select value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option>Todos</option><option>Aprovado</option><option>Em análise</option><option>Reprovado</option><option>Banco</option></select></label><label>PCD<select value={pcdFilter} onChange={e=>setPcdFilter(e.target.value)}><option>Todos</option><option>Sim</option><option>Não</option></select></label><label>Saídas da tela<select value={focusFilter} onChange={e=>setFocusFilter(e.target.value)}><option>Todos</option><option>Com ocorrências</option><option>Sem ocorrências</option></select></label><button type="button" className="clearFilters" onClick={()=>{setQuery("");setStatusFilter("Todos");setPcdFilter("Todos");setFocusFilter("Todos");setSortKey("overall");setSortDir("desc")}}>Limpar filtros</button><span>{list.length} de {results.length} candidato(s)</span></div><div className="table"><table><thead><tr><th><button type="button" className="sortableHeader" onClick={()=>toggleSort("name" as SortKey)}>Candidato{sortMark("name" as SortKey)}</button></th><th><button type="button" className="sortableHeader" onClick={()=>toggleSort("pcd" as SortKey)}>PCD{sortMark("pcd" as SortKey)}</button></th><th><button type="button" className="sortableHeader" onClick={()=>toggleSort("wpm" as SortKey)}>Digitação{sortMark("wpm" as SortKey)}</button></th><th><button type="button" className="sortableHeader" onClick={()=>toggleSort("plates" as SortKey)}>Placas{sortMark("plates" as SortKey)}</button></th><th><button type="button" className="sortableHeader" onClick={()=>toggleSort("windows" as SortKey)}>Informática{sortMark("windows" as SortKey)}</button></th><th><button type="button" className="sortableHeader" onClick={()=>toggleSort("infractions" as SortKey)}>OCR{sortMark("infractions" as SortKey)}</button></th><th>Prática</th><th>Tempo total</th><th><button type="button" className="sortableHeader" onClick={()=>toggleSort("attention" as SortKey)}>Saídas da tela{sortMark("attention" as SortKey)}</button></th><th><button type="button" className="sortableHeader" onClick={()=>toggleSort("overall" as SortKey)}>Geral{sortMark("overall" as SortKey)}</button></th><th><button type="button" className="sortableHeader" onClick={()=>toggleSort("status" as SortKey)}>Status{sortMark("status" as SortKey)}</button></th><th>Ações</th></tr></thead><tbody>{list.map((r,i)=><tr key={r.id||`${r.email}-${i}`}><td><button className="candidateName" onClick={()=>setSelectedResult(r)}>{r.name}</button></td><td><span className={`pcdBadge ${readProfile(r).pcd==="Sim"?"yes":"no"}`}>{readProfile(r).pcd||"Não informado"}</span></td><td><b>{r.wpm} ppm</b><small>{r.accuracy}% precisão</small><small className="timeResult">◷ {readTimes(r).typing?formatTime(readTimes(r).typing):"não registrado"}</small></td><td><b>{r.plates}%</b><small className="timeResult">◷ {readTimes(r).plates?formatTime(readTimes(r).plates):"não registrado"}</small></td><td>{r.windows}%</td><td>{r.infractions}%</td><td>{readPracticalScore(r)}%</td><td><b>{readTimes(r).total?formatTime(readTimes(r).total):"Não registrado"}</b></td><td><b>{readAttention(r).count}</b><small>{readAttention(r).total?formatTime(readAttention(r).total):"nenhuma"}</small></td><td><strong>{r.overall}%</strong></td><td><select className={`statusSelect ${statusClass(r.status)}`} aria-label={`Status de ${r.name}`} value={r.status==="Não aprovado"?"Reprovado":r.status} onChange={e=>updateStatus(r,e.target.value)}><option>Reprovado</option><option>Aprovado</option><option>Em análise</option><option>Banco</option></select></td><td><button className="deleteCandidate" onClick={()=>deleteCandidate(r)} aria-label={`Excluir dados de ${r.name}`}>Excluir</button></td></tr>)}</tbody></table></div></section>;
  return <div className="admin"><aside><Logo/><nav><button className={adminTab==="overview"?"selected":""} onClick={()=>setAdminTab("overview")}>▦ Visão geral</button><button className={adminTab==="candidates"?"selected":""} onClick={()=>setAdminTab("candidates")}>♙ Candidatos</button><button className={adminTab==="questions"?"selected":""} onClick={()=>setAdminTab("questions")}>▤ Banco de questões</button><button className={adminTab==="settings"?"selected":""} onClick={()=>setAdminTab("settings")}>⚙ Configurações</button></nav><button onClick={()=>setView("access")}>↪ Sair</button></aside><main><div className="adminHead"><div><label>PAINEL ADMINISTRATIVO</label><h1>{adminTab==="overview"?"Resultados dos candidatos":adminTab==="candidates"?"Candidatos":adminTab==="questions"?"Editar todas as etapas":"Configurações"}</h1><p>{adminTab==="questions"?"Personalize o conteúdo completo da avaliação.":adminTab==="settings"?"Parâmetros gerais do processo seletivo.":"Acompanhe o desempenho e identifique os melhores perfis."}</p></div><i>CM</i></div>{adminTab==="overview"&&<><section className="kpis"><article><small>Total de candidatos</small><b>{results.length}</b><em>↗ atualizado agora</em></article><article><small>Média geral</small><b>{avg}%</b><em>meta recomendada: 80%</em></article><article><small>Aprovados</small><b>{results.filter(r=>r.status==="Aprovado").length}</b><em>melhores desempenhos</em></article><article><small>Em análise</small><b>{results.filter(r=>r.status==="Em análise").length}</b><em>requer revisão</em></article></section>{table}</>}{adminTab==="candidates"&&<div className="adminSection">{table}</div>}{adminTab==="questions"&&<AdminTestEditor typingText={typingText} setTypingText={setTypingText} plates={testPlates} setPlates={setTestPlates} questions={questions} editQuestion={editQuestion} deleteQuestion={deleteQuestion} setQuestions={setQuestions} ocrCases={ocrCases} setOcrCases={setOcrCases} practicalConfig={practicalConfig} setPracticalConfig={setPracticalConfig} save={saveQuestions} saving={savingQuestions} message={questionMessage}/>} {adminTab==="settings"&&<section className="settingsPanel"><h2>Critérios da avaliação</h2><div><label>Nota para aprovação<input value="85%" readOnly/></label><label>Faixa para análise<input value="70% a 84%" readOnly/></label><label>Número de tentativas<input value="2" readOnly/></label><label>Análise prática<input value="Correção automática · etapa 5" readOnly/></label></div><p>Os parâmetros estão ativos para este processo seletivo.</p></section>}</main>{selectedResult&&<CandidateDetails result={selectedResult} questions={questions} onClose={()=>setSelectedResult(null)}/>}</div>
 }
 if(step<0)return <div className="page"><header><Logo/><button className="link" onClick={()=>setView("access")}>← Voltar</button></header><main className="intro"><section><label>BEM-VINDO(A)</label><h1>Sua avaliação começa aqui.</h1><p>Preencha seus dados e conheça as etapas. Reserve um ambiente tranquilo e use um computador com teclado.</p><div className="stageList">{[["⌨","Digitação","Velocidade e precisão","Texto ampliado"],["▣","Placas de veículos","Leitura e digitação","5 placas"],["⊞","Informática básica","Conhecimentos e atalhos","10 questões"],["⌕","Análise OCR","Conferência de placa e categoria","5 casos"],["◎","Análise prática","Análise completa da ocorrência","5 casos"]].map((x,i)=><article key={x[1]}><i>{x[0]}</i><span><small>ETAPA {i+1}</small><b>{x[1]}</b><p>{x[2]}</p></span><em>{x[3]}</em></article>)}</div></section><form onSubmit={e=>{e.preventDefault();testStartedAt.current=Date.now();setStep(0)}}><h2>Identificação</h2><p>Informe os dados usados na sua candidatura.</p><div className="focusWarning"><b>⚠ Monitoramento durante a avaliação</b><p>Não minimize a tela nem alterne para outra aba ou janela. Essas ocorrências serão registradas e analisadas pela equipe responsável.</p></div><label>Nome completo<input required placeholder="Digite seu nome" value={user.name} onChange={e=>setUser({...user,name:e.target.value})}/></label><label>E-mail<input required type="email" placeholder="seu@email.com" value={user.email} onChange={e=>setUser({...user,email:e.target.value})}/></label><label>Telefone<input required type="tel" autoComplete="tel" placeholder="(41) 99999-9999" value={user.phone} onChange={e=>setUser({...user,phone:e.target.value})}/></label><label>Endereço completo<textarea className="addressField" required placeholder="Rua, número, complemento, bairro e cidade" value={user.address} onChange={e=>setUser({...user,address:e.target.value})}/></label><label>PCD — Pessoa com Deficiência<select required value={user.pcd} onChange={e=>setUser({...user,pcd:e.target.value as CandidateProfile["pcd"]})}><option value="">Selecione</option><option value="Sim">Sim</option><option value="Não">Não</option></select></label><button>Iniciar avaliação →</button><small>Ao continuar, você concorda com o uso dos dados para fins deste processo seletivo.</small></form></main></div>;
 if(step===5){const r=results[0];return <div className="page"><header><Logo/></header><main className="finish"><i>✓</i><label>AVALIAÇÃO CONCLUÍDA</label><h1>Obrigada, {user.name.split(" ")[0]}!</h1><p>Suas respostas foram registradas. A equipe responsável analisará o resultado e entrará em contato pelos canais informados.</p><div className="score"><b>{r.overall}%</b><small>pontuação geral</small></div><section><span>⌨ Digitação <b>{r.wpm} palavras · {r.accuracy}%</b></span><span>▣ Placas <b>{r.plates}%</b></span><span>⊞ Informática <b>{r.windows}%</b></span><span>⌕ Análise OCR <b>{r.infractions}%</b></span><span>◎ Análise prática <b>{readPracticalScore(r)}%</b></span></section><button onClick={()=>location.reload()}>Voltar ao início</button></main></div>}
 return <div className="page"><header><Logo/><small className="timer">◷ Avaliação em andamento</small></header><Progress step={step}/><main className={`test ${step>=3?"practicalTest":""}`}><div className="testHead"><i>{["⌨","▣","⊞","⌕","◎"][step]}</i><span><label>ETAPA {step+1} DE 5</label><h1>{["Teste de digitação","Digitação de placas","Informática básica","Análise de leitura OCR","Análise completa da ocorrência"][step]}</h1><p>{["Digite o texto abaixo com atenção.","Transcreva exatamente os caracteres exibidos.","Assinale as alternativas corretas.","Compare a leitura automática com a imagem e identifique divergências.","Analise as imagens e responda todas as questões de cada ocorrência."][step]}</p></span></div>
 {step===0&&<><div className="stageClock"><span>◷ Tempo da digitação</span><b>{formatTime(stageSeconds)}</b></div><blockquote className="protectedSource typingReference" onCopy={blockClipboard} onCut={blockClipboard} onContextMenu={e=>e.preventDefault()} onDragStart={e=>e.preventDefault()}>{[...typingText].map((character,i)=><span className={i>=typed.length?"pending":typed[i]===character?"correct":"incorrect"} key={i}>{character}</span>)}</blockquote><p className="clipboardNotice">Por segurança, copiar, recortar e colar estão desativados nesta etapa.</p><textarea autoFocus autoComplete="off" placeholder="Comece a digitar aqui..." value={typed} onChange={e=>setTyped(e.target.value)} onCopy={blockClipboard} onCut={blockClipboard} onPaste={blockClipboard} onContextMenu={e=>e.preventDefault()} onKeyDown={blockClipboardKeys}/><div className="live"><span>Velocidade <b>{stats.wpm} ppm</b></span><span>Precisão <b>{stats.accuracy}%</b></span><span>Caracteres <b>{typed.length}</b></span></div><button className="next" disabled={!typed} onClick={()=>{setStageTimes(current=>({...current,typing:stageSeconds}));setStageSeconds(0);setStep(1)}}>Continuar →</button></>}
 {step===1&&<><div className="stageClock"><span>◷ Tempo das placas</span><b>{formatTime(stageSeconds)}</b></div><p className="clipboardNotice">Digite cada placa manualmente. Copiar, recortar e colar estão desativados.</p><div className="plateGrid">{testPlates.map((p,i)=><article key={`${i}-${p}`}><div className="plate protectedSource" onCopy={blockClipboard} onCut={blockClipboard} onContextMenu={e=>e.preventDefault()} onDragStart={e=>e.preventDefault()}><small>BRASIL</small><b>{p}</b></div><label>Digite a placa<input maxLength={7} autoComplete="off" placeholder="AAA0A00" value={pa[i]||""} onChange={e=>{const n=[...pa];n[i]=e.target.value.toUpperCase();setPa(n)}} onCopy={blockClipboard} onCut={blockClipboard} onPaste={blockClipboard} onContextMenu={e=>e.preventDefault()} onKeyDown={blockClipboardKeys}/></label></article>)}</div><button className="next" disabled={testPlates.some((_,i)=>(pa[i]||"").length<7)} onClick={()=>{setStageTimes(current=>({...current,plates:stageSeconds}));setStageSeconds(0);setStep(2)}}>Continuar →</button></>}
 {step===2&&<><div className="quiz">{questions.map((q,i)=><article key={`${i}-${q[0]}`}><i>{i+1}</i><section><h3>{q[0]}</h3><div className="options three">{q[1].map((o,j)=><button className={wa[i]===j?"chosen":""} onClick={()=>answer(wa,setWa,i,j)} key={o}><b>{String.fromCharCode(65+j)})</b> {o}</button>)}</div></section></article>)}</div><button className="next" disabled={wa.filter(x=>x!==undefined).length<questions.length} onClick={()=>setStep(3)}>Continuar para a análise OCR →</button></>}
 {step===3&&<div className="ocrCases"><div className="practicalNotice"><b>Análise de leitura OCR</b><span>Clique na imagem para ampliar. Confira a placa e a categoria separadamente.</span></div>{ocrCases.map((item,i)=><article className="ocrCase" key={item.image}><div className="caseHeader"><span>CASO {i+1} DE {ocrCases.length}</span><h2>Conferência da leitura automática</h2></div><figure className="zoomableImage" role="button" tabIndex={0} onClick={()=>setLightbox({images:[item.image],index:0})}><img src={item.image} alt={`Veículo do caso OCR ${i+1}`}/><figcaption>Clique para ampliar e usar o zoom ⤢</figcaption></figure><div className="ocrReading"><span><small>PLACA EXIBIDA PELO OCR</small><b>{item.ocrPlate}</b></span><span><small>CATEGORIA EXIBIDA</small><b>{item.shownCategory}</b></span></div><div className="ocrChecks"><fieldset><legend>A leitura da placa está correta?</legend><div className="caseOptions"><button type="button" className={ocrAnswers[i]?.plateStatus==="correct"?"selected":""} onClick={()=>updateOcr(i,{plateStatus:"correct",correctedPlate:""})}>Placa correta</button><button type="button" className={ocrAnswers[i]?.plateStatus==="divergent"?"selected":""} onClick={()=>updateOcr(i,{plateStatus:"divergent"})}>Caractere divergente</button></div>{ocrAnswers[i]?.plateStatus==="divergent"&&<label>Digite a placa correta<input maxLength={7} value={ocrAnswers[i].correctedPlate} onChange={e=>updateOcr(i,{correctedPlate:e.target.value.toUpperCase()})} placeholder="AAA0A00"/></label>}</fieldset><fieldset><legend>A categoria está correta?</legend><div className="caseOptions"><button type="button" className={ocrAnswers[i]?.categoryStatus==="correct"?"selected":""} onClick={()=>updateOcr(i,{categoryStatus:"correct",correctedCategory:""})}>Categoria correta</button><button type="button" className={ocrAnswers[i]?.categoryStatus==="divergent"?"selected":""} onClick={()=>updateOcr(i,{categoryStatus:"divergent"})}>Categoria divergente</button></div>{ocrAnswers[i]?.categoryStatus==="divergent"&&<label>Selecione a categoria correta<select value={ocrAnswers[i].correctedCategory} onChange={e=>updateOcr(i,{correctedCategory:e.target.value})}><option value="">Selecione</option><option>CARRO</option><option>MOTO</option><option>CAMINHÃO</option></select></label>}</fieldset></div></article>)}<button className="next practicalFinish" disabled={!ocrComplete} onClick={()=>setStep(4)}>Continuar para a análise prática →</button></div>}
 {step===4&&<div className="practicalCases"><div className="practicalNotice"><b>Teste prático</b><span>Clique ou toque nas imagens para ampliar e conferir a placa do veículo.</span></div>{practicalCases.map((item,i)=><article className="caseCard" key={i}><div className="caseHeader"><span>OCORRÊNCIA {i+1} DE {practicalCases.length}</span><h2>Análise das imagens</h2></div><div className={`caseImages images${item.images.length}`}>{item.images.map((src,j)=><figure className="zoomableImage" role="button" tabIndex={0} key={src} onClick={()=>setLightbox({images:item.images,index:j})} onKeyDown={e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();setLightbox({images:item.images,index:j})}}}><img src={src} alt={`Ocorrência ${i+1} — imagem ${j+1}`}/><figcaption>Imagem {j+1} · Clique para ampliar ⤢</figcaption></figure>)}</div><div className="caseFields"><label>1. {practicalConfig.platePrompt}<input value={practical[i].plate} onChange={e=>updatePractical(i,"plate",e.target.value.toUpperCase())} placeholder="Digite a placa identificada"/></label><fieldset><legend>2. {practicalConfig.vehiclePrompt}</legend><div className="caseOptions">{practicalConfig.vehicleTypes.map(x=><button type="button" className={practical[i].vehicle===x?"selected":""} onClick={()=>updatePractical(i,"vehicle",x)} key={x}>{x}</button>)}</div></fieldset><fieldset><legend>3. {practicalConfig.infractionPrompt}</legend><div className="caseOptions infractions">{practicalConfig.infractionTypes.map(x=><button type="button" className={practical[i].infraction===x?"selected":""} onClick={()=>updatePractical(i,"infraction",x)} key={x}>{x}</button>)}</div></fieldset><fieldset><legend>4. {practicalConfig.validityPrompt}</legend><div className="caseOptions"><button type="button" className={practical[i].validity==="VÁLIDA"?"selected":""} onClick={()=>updatePractical(i,"validity","VÁLIDA")}>Válida</button><button type="button" className={practical[i].validity==="INVÁLIDA"?"selected":""} onClick={()=>updatePractical(i,"validity","INVÁLIDA")}>Inválida</button></div></fieldset><label>Justificativa ou observação (opcional)<textarea value={practical[i].justification} onChange={e=>updatePractical(i,"justification",e.target.value)} placeholder="Este campo ficará disponível para análise da equipe"/></label></div></article>)}<button className="next practicalFinish" onClick={finish}>Finalizar avaliação ✓</button></div>}
 </main>{lightbox&&<ImageLightbox images={lightbox.images} index={lightbox.index} setIndex={index=>setLightbox({...lightbox,index})} onClose={()=>setLightbox(null)}/>}</div>
}
